:root{--color-surface:#FFFFFF;--color-ink:#221A12;--color-accent:#D98E1E;--color-civic:#203DA5;--color-civic-ink:#14265B;--color-civic-muted:#536185;--color-civic-line:#CCD5ED;--radius-ngo:4px;--radius-square:0px;--spacing-page:72px;--spacing-section:88px;--spacing-block:32px;--spacing-item:24px;--spacing-tight:16px;--spacing-micro:8px;--spacing-compact:12px;--spacing-wide:48px;--spacing-large:64px;--font-ngo:DM Sans, sans-serif;--font-civic:Space Grotesk, sans-serif;--text-h1:52px;--text-h2:32px;--text-h3:20px;--text-body:16px;--text-small:13px;--text-poster:88px;--text-lead:24px}
*{box-sizing:border-box}body,h1,h2,h3,p,ul,ol,figure,dl{margin:0}a{color:inherit}a:focus-visible{outline:3px solid var(--color-civic);outline-offset:4px}

 .csh, .csh {font-family:var(--font-ngo);color:var(--color-civic-ink)}
 .csh-bar, .csh-bar {background:var(--color-civic-ink);color:var(--color-surface);font-size:var(--text-small);padding:var(--spacing-compact) var(--spacing-page);display:flex;justify-content:space-between;align-items:center}
 .csh-bar a, .csh-bar a {color:var(--color-surface);font-weight:700;text-underline-offset:5px}
 .csh-main, .csh-main {background:var(--color-surface);border-bottom:1px solid var(--color-civic-line);padding:var(--spacing-tight) var(--spacing-page);display:flex;align-items:center;justify-content:space-between;gap:var(--spacing-block)}
 .csh-mark, .csh-mark {font-family:var(--font-civic);font-size:var(--text-h3);font-weight:700;line-height:1.05;letter-spacing:-.01em;color:var(--color-civic);text-decoration:none}
 .csh-nav, .csh-nav {display:flex;gap:var(--spacing-item);align-items:center;font-weight:500}
 .csh-actions, .csh-actions {display:flex;gap:var(--spacing-compact);color:var(--color-civic)}


 .cpi, .cpi {margin:0 var(--spacing-page);padding:var(--spacing-section) 0 var(--spacing-wide);display:grid;grid-template-columns:1.5fr 1fr;gap:var(--spacing-large);align-items:end;border-bottom:1px solid var(--color-civic);font-family:var(--font-ngo)}
 .cpi-eyebrow, .cpi-eyebrow {margin:0;font-size:var(--text-small);font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--color-civic)}
 .cpi-title, .cpi-title {margin:var(--spacing-tight) 0 0;font-family:"Space Grotesk",sans-serif;font-size:var(--text-poster);line-height:.98;font-weight:500;letter-spacing:-.06em;color:var(--color-civic)}
 .cpi-lede, .cpi-lede {margin:0;font-size:var(--text-h3);line-height:1.5;color:var(--color-civic-muted);max-width:460px}


 .ev, .ev {display:grid;grid-template-columns:112px 1fr auto;gap:var(--spacing-block);align-items:center;padding:var(--spacing-item) 0;border-top:1px solid var(--color-civic-line);font-family:var(--font-ngo);color:var(--color-civic-ink)}
 .ev-date, .ev-date {display:flex;flex-direction:column;align-items:center;justify-content:center;height:112px;background:var(--color-civic);color:var(--color-surface);font-family:var(--font-civic)}
 .ev-m, .ev-m {font-size:var(--text-h2);font-weight:500;line-height:1;letter-spacing:-.02em}
 .ev-d, .ev-d {font-size:var(--text-small);text-transform:uppercase;letter-spacing:.1em;margin-top:var(--spacing-micro)}
 .ev-status, .ev-status {margin:0 0 var(--spacing-micro);font-size:var(--text-small);font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--color-civic)}
 .ev-title, .ev-title {margin:0 0 var(--spacing-micro);font-family:var(--font-civic);font-size:var(--text-lead);font-weight:500;letter-spacing:-.02em;color:var(--color-civic)}
 .ev-meta, .ev-meta {margin:0;color:var(--color-civic-muted);max-width:62ch}
 .ev-link, .ev-link {display:inline-flex;align-items:center;min-height:48px;padding:0 var(--spacing-item);border:1px solid var(--color-civic);color:var(--color-civic);font-weight:700;text-decoration:none}
 .ev-link:hover, .ev-link:hover {background:var(--color-civic);color:var(--color-surface)}
 .ev-link:focus-visible, .ev-link:focus-visible {outline:3px solid var(--color-civic);outline-offset:4px}


 .ngo-button, .ngo-button {display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:var(--spacing-tight) var(--spacing-item);font:inherit;font-weight:700;text-decoration:none;border:1px solid transparent;border-radius:var(--radius-ngo);background:var(--color-ink);color:var(--color-surface)}
 .ngo-button[data-tone="amber"], .ngo-button[data-tone="amber"] {background:var(--color-accent);color:var(--color-ink)}
 .ngo-button[data-tone="civic"], .ngo-button[data-tone="civic"] {background:var(--color-civic);color:var(--color-surface);border-radius:var(--radius-square)}
 .ngo-button[data-tone="outline"], .ngo-button[data-tone="outline"] {background:transparent;color:inherit;border-color:currentColor;border-radius:var(--radius-square)}
 .ngo-button:hover, .ngo-button:hover {opacity:.85}
 .ngo-button:focus-visible, .ngo-button:focus-visible {outline:3px solid currentColor;outline-offset:4px}


 .cab, .cab {margin:var(--spacing-section) var(--spacing-page);padding:var(--spacing-wide);border:1px solid var(--color-civic);display:flex;justify-content:space-between;align-items:center;gap:var(--spacing-block);font-family:var(--font-ngo)}
 .cab-title, .cab-title {margin:0;font-family:var(--font-civic);font-size:var(--text-h1);line-height:1.05;font-weight:500;letter-spacing:-.04em;color:var(--color-civic)}
 .cab-meta, .cab-meta {margin:var(--spacing-compact) 0 0;color:var(--color-civic-muted)}
 .cab-actions, .cab-actions {display:flex;gap:var(--spacing-compact);color:var(--color-civic);flex:none}


 .ngo-navlink, .ngo-navlink {display:inline-block;padding:var(--spacing-compact) 0;color:inherit;font:inherit;text-decoration:none}
 .ngo-navlink:hover, .ngo-navlink:hover {text-decoration:underline;text-underline-offset:5px}
 .ngo-navlink[data-state="current"], .ngo-navlink[data-state="current"] {text-decoration:underline;text-underline-offset:6px;text-decoration-thickness:2px;font-weight:700}
 .ngo-navlink:focus-visible, .ngo-navlink:focus-visible {outline:2px solid currentColor;outline-offset:4px}
